INSERT INTO `patient_identifier_type` VALUES (1,'OpenMRS Identification Number','Unique number used in OpenMRS','',1,1,'2005-09-22 00:00:00',0,NULL,'org.openmrs.patient.impl.LuhnIdentifierValidator',NULL,0,NULL,NULL,NULL,'8d793bee-c2cc-11de-8d13-0010c6dffd0f',NULL,NULL,NULL),(2,'Old Identification Number','Number given out prior to the OpenMRS system (No check digit)','',0,1,'2005-09-22 00:00:00',0,NULL,NULL,NULL,0,NULL,NULL,NULL,'8d79403a-c2cc-11de-8d13-0010c6dffd0f',NULL,NULL,NULL),(3,'OpenMRS ID','OpenMRS patient identifier, with check-digit',NULL,0,2,'2024-06-18 11:54:32',1,NULL,'org.openmrs.module.idgen.validator.LuhnMod30IdentifierValidator','NOT_USED',0,NULL,NULL,NULL,'05a29f94-c0ed-11e2-94be-8c13b969e334','UNIQUE',NULL,NULL),(4,'Legacy ID','Identifier type to record optional previous identifers',NULL,0,2,'2024-06-18 11:54:32',0,NULL,NULL,'NOT_USED',0,NULL,NULL,NULL,'22348099-3873-459e-a32e-d93b17eda533',NULL,NULL,NULL),(5,'ID Card','ID Card',NULL,0,2,'2024-06-18 11:54:32',0,NULL,NULL,'NOT_USED',0,NULL,NULL,NULL,'b4143563-16cd-4439-b288-f83d61670fc8','UNIQUE',NULL,NULL),(6,'SSN','Social Security Number','[A-Z]{1}-[0-9]{7}',0,2,'2024-06-18 11:54:32',0,'Identifier should be 1 letter, followed by a dash and 7 numerical characters. Eg, A-0010902',NULL,'NOT_USED',0,NULL,NULL,NULL,'a71403f3-8584-4289-ab41-2b4e5570bd45','UNIQUE',NULL,NULL);
